export interface ICatalogButton {
	/** Command id: an existing command, or `saengine.catalog.<tab>.<slug>` for a planned feature. */
	readonly id: string;
	readonly planned: boolean;
	readonly label: string;
	readonly description: string;
	readonly size: 'large' | 'small';
	/** A Codicon name. */
	readonly icon: string;
	/** The built feature behind the button (saengine.features): its panel's inputs. */
	readonly feature?: ICatalogFeature;
}

export interface ICatalogField {
	readonly key: string;
	readonly label: string;
	readonly type: 'number' | 'text' | 'select' | 'checkbox';
	readonly defaultValue: string | number | boolean;
	readonly options?: readonly { readonly value: string; readonly label: string }[];
	readonly min?: number;
	readonly max?: number;
	readonly help?: string;
}

export interface ICatalogFeature {
	readonly help: string;
	readonly fields: readonly ICatalogField[];
}

export interface ICatalogGroup {
	readonly tab: string;
	/** The menu group, `<order>_<key>`; the key carries the label. */
	readonly group: string;
	readonly key: string;
	readonly label: string;
	readonly part: string;
	readonly buttons: readonly ICatalogButton[];
}

